import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;
import org.json.*;

public class AssetInventoryServlet extends HttpServlet {
    private static final Logger logger = Logger.getLogger(AssetInventoryServlet.class.getName());
    private static final String DB_URL = System.getenv("INVENTORY_DB_URL");
    private static final String DB_USER = System.getenv("INVENTORY_DB_USER");
    private static final String DB_PASS = System.getenv("INVENTORY_DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String assetType = req.getParameter("type");
        String location = req.getParameter("location");
        String sortField = req.getParameter("sort");
        String tenantId = req.getHeader("X-Tenant-ID");

        if (tenantId == null || tenantId.isEmpty()) {
            resp.sendError(403, "Missing tenant context");
            return;
        }

        // Validate asset type against known enum
        if (!isValidAssetType(assetType)) {
            resp.sendError(400, "Invalid asset type");
            return;
        }

        // Build query with tenant isolation
        StringBuilder query = new StringBuilder();
        query.append("SELECT asset_id, name, location, status, last_scan_date ");
        query.append("FROM asset_inventory WHERE tenant_id = ? AND asset_type = ?");

        if (location != null && !location.isEmpty()) {
            // Location filter uses parameterized approach
            query.append(" AND location = ?");
        }

        // Sort field - validated against allowlist but with fallback
        if (sortField != null && !sortField.isEmpty()) {
            if (isAllowedSortField(sortField)) {
                query.append(" ORDER BY ").append(sortField);
            } else {
                // Legacy compatibility: some integrations pass qualified names
                // Strip table prefix if present and re-check
                String stripped = sortField.contains(".") ?
                    sortField.substring(sortField.lastIndexOf('.') + 1) : sortField;
                if (isAllowedSortField(stripped)) {
                    query.append(" ORDER BY ").append(sortField);
                }
            }
        }

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement stmt = conn.prepareStatement(query.toString())) {

            stmt.setString(1, tenantId);
            stmt.setString(2, assetType);
            if (location != null && !location.isEmpty()) {
                stmt.setString(3, location);
            }

            ResultSet rs = stmt.executeQuery();
            JSONArray results = new JSONArray();
            while (rs.next()) {
                JSONObject asset = new JSONObject();
                asset.put("asset_id", rs.getString("asset_id"));
                asset.put("name", rs.getString("name"));
                asset.put("location", rs.getString("location"));
                asset.put("status", rs.getString("status"));
                asset.put("last_scan_date", rs.getString("last_scan_date"));
                results.put(asset);
            }

            resp.setContentType("application/json");
            resp.getWriter().write(results.toString());

        } catch (SQLException e) {
            logger.log(Level.SEVERE, "Query failed for tenant " + tenantId, e);
            resp.sendError(500, "Internal error");
        }
    }

    private boolean isValidAssetType(String type) {
        if (type == null) return false;
        String[] valid = {"server", "workstation", "network_device", "iot", "virtual_machine"};
        for (String v : valid) {
            if (v.equalsIgnoreCase(type)) return true;
        }
        return false;
    }

    private boolean isAllowedSortField(String field) {
        if (field == null) return false;
        String[] allowed = {"name", "location", "status", "last_scan_date", "asset_id"};
        for (String a : allowed) {
            if (a.equalsIgnoreCase(field)) return true;
        }
        return false;
    }
}
